-- 修改后，此任务测试级别需要提高，务必保障其严谨；生成任务限制了需要在运行当日完成，否则就自杀；配置有DQC的warning监控，检测升级数量波动；
-- 用减法算出7天的增量指标，这里为了降低复杂度，其实是比7天少2个小时的，是6天22小时
set max_partition_${grass_region_without_quote} = (
select
    max(time_str) as max_time_str -- 如果迁移不支持这个语法，可以中间落一次盘，或者sql写的冗余一些也能解决
from(
    SELECT
        concat(local_date,'_',if(local_hour<10,concat('0',local_hour),local_hour)) as  time_str
    FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_realtime_metrics_hf
    where grass_region in (${grass_region}) and local_date = ${local_date}
    group by local_date,local_hour -- daily 指标对齐tracker，采用local时间结算一天
) a
);
--sql_divide_splitter--

set min_partition_${grass_region_without_quote} = (
select
    min(time_str) as min_time_str
from(
    SELECT
        concat(local_date,'_',if(local_hour<10,concat('0',local_hour),local_hour)) as  time_str
    FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_realtime_metrics_hf
    where grass_region in (${grass_region}) and local_date = date_sub(${local_date}, 6)
    group by local_date,local_hour -- daily 指标对齐tracker，采用local时间结算一天
) a
);
--sql_divide_splitter--

CREATE TEMPORARY VIEW max_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,cspu_id
    ,item_id
    ,version_date -- base的值，honggen那里写死了，为0
    ,sum(if(traffic_tag='preferred',imp_cnt_nd,0)) preferred_imp_cnt_nd
    ,sum(if(traffic_tag='preferred',click_cnt_nd,0)) preferred_click_cnt_nd
    ,sum(if(traffic_tag='base',imp_cnt_nd,0)) cspu_imp_cnt_nd
    ,sum(if(traffic_tag='base',click_cnt_nd,0)) cspu_click_cnt_nd
FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_realtime_metrics_hf
where grass_region in (${grass_region}) and local_date = split(${max_partition_${grass_region_without_quote}},'_')[0]
and local_hour = cast(split(${max_partition_${grass_region_without_quote}},'_')[1] as int)
and traffic_tag in ('preferred','base') -- 计算监控回退只需要preferred的指标和cspu指标
group by 1,2,3,4
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW min_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,cspu_id
    ,item_id
    ,version_date
    ,sum(if(traffic_tag='preferred',imp_cnt_nd,0)) preferred_imp_cnt_nd
    ,sum(if(traffic_tag='preferred',click_cnt_nd,0)) preferred_click_cnt_nd
    ,sum(if(traffic_tag='base',imp_cnt_nd,0)) cspu_imp_cnt_nd
    ,sum(if(traffic_tag='base',click_cnt_nd,0)) cspu_click_cnt_nd
FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_realtime_metrics_hf
where grass_region in (${grass_region}) and local_date = split(${min_partition_${grass_region_without_quote}},'_')[0]
and local_hour = cast(split(${min_partition_${grass_region_without_quote}},'_')[1] as int)
and traffic_tag in ('preferred','base')
group by 1,2,3,4
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW preferred_day_cnt_${grass_region_without_quote} AS
SELECT -- 用于辅助判定持续preferred的天数，出现在这里，就说明在此表task运行日8.8->所对应的的监控指标日8.7->的6天前8.1那天，就成为了preferred。成为preferred状态后，首次接受监控的prefered的存续时长一般为[6.5,7.5]
     exp_tag
    ,cspu_id
    ,item_id
    ,version_date
FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_status_hf
where grass_region in (${grass_region}) and regional_date = date_sub(${local_date}, 7)
and regional_hour = (select max(regional_hour) from srdi_mart.dwd_sr_data_warehouse_pb_search_replace_status_hf where grass_region in (${grass_region}) and regional_date = date_sub(${local_date}, 7))
and exploration_status='preferred' -- 要当时就成为preferred的组合key
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW current_preferred_${grass_region_without_quote} AS
SELECT -- 用来找到当前还处于prefered状态的组合，用来解决version_date更新延迟的问题
     exp_tag
    ,cspu_id
    ,item_id
    ,version_date
FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_status_hf
where grass_region in (${grass_region}) and regional_date = ${local_date}
and regional_hour = data_infra.max_pt('srdi_mart.dwd_sr_data_warehouse_pb_search_replace_status_hf', 'regional_hour', "grass_region=${grass_region} and regional_date = ${local_date}")
and exploration_status='preferred'
and version_date < replace(date_sub(${local_date}, 6), '-', '') --防止极端case在7天内完成多次探索 (分区时间是8.24，它本轮的版本开始时间至少要是8.17，8.18不行，因为8.17的值是8.18更新上去的)
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW last_monitoring_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,cspu_id
    ,item_id
    ,version_date
FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_monitoring_nd
WHERE grass_region IN (${grass_region})
and local_date = data_infra.max_pt('srdi_mart.dwd_sr_data_warehouse_pb_search_replace_monitoring_nd', 'local_date', "grass_region=${grass_region} and local_date < ${local_date}")
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW version_cnt_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,cspu_id
    ,item_id
    ,count(distinct version_date) as version_cnt
FROM last_monitoring_${grass_region_without_quote}
group by 1,2,3
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW update_version_list_${grass_region_without_quote} AS
select
     f.exp_tag
    ,f.cspu_id
    ,f.item_id
    ,cast(replace(date_add(${local_date},1), '-', '') as int) as version_date --用任务运行日作为版本号
    ,cast(replace(${local_date}, '-', '') as int) as join_key_date --用昨日作为关联主键，防止反复送去升级
from(
    select
         c.*
        ,coalesce(d1.preferred_imp_cnt_nd,0)-coalesce(e1.preferred_imp_cnt_nd,0) as preferred_imp_cnt_7d
        ,coalesce(d1.preferred_click_cnt_nd,0)-coalesce(e1.preferred_click_cnt_nd,0) as preferred_click_cnt_7d
        ,coalesce(d2.cspu_imp_cnt_nd,0)-coalesce(e2.cspu_imp_cnt_nd,0) as cspu_imp_cnt_7d
        ,coalesce(d2.cspu_click_cnt_nd,0)-coalesce(e2.cspu_click_cnt_nd,0) as cspu_click_cnt_7d
    from(
        select
             a.exp_tag
            ,a.cspu_id
            ,a.item_id
            ,a.version_date
        from current_preferred_${grass_region_without_quote} a -- 圈选出当前是preferred 且 存续此状态至少7天的组合key
        inner join preferred_day_cnt_${grass_region_without_quote} b on a.item_id=b.item_id and a.cspu_id=b.cspu_id and a.exp_tag=b.exp_tag and a.version_date=b.version_date
    ) c
    left join max_${grass_region_without_quote} d1 on c.item_id=d1.item_id and c.cspu_id=d1.cspu_id and c.exp_tag=d1.exp_tag and c.version_date=d1.version_date
    left join max_${grass_region_without_quote} d2 on c.item_id=d2.item_id and c.cspu_id=d2.cspu_id and d2.exp_tag='control'
    left join min_${grass_region_without_quote} e1 on c.item_id=e1.item_id and c.cspu_id=e1.cspu_id and c.exp_tag=e1.exp_tag and c.version_date=e1.version_date
    left join min_${grass_region_without_quote} e2 on c.item_id=e2.item_id and c.cspu_id=e2.cspu_id and e2.exp_tag='control'
    where d1.item_id is not null and d2.item_id is not null and e1.item_id is not null and e2.item_id is not null -- 数据为空的兜底清楚，万一用作减法的两个分区没取到，这时候就让本次监控回退失效
) f
left join version_cnt_${grass_region_without_quote} g on f.item_id=g.item_id and f.cspu_id=g.cspu_id and f.exp_tag=g.exp_tag
where (g.version_cnt is null or g.version_cnt<10) -- 限定rollback 次数，暂定为10
and coalesce(preferred_click_cnt_7d/preferred_imp_cnt_7d,0) < coalesce(cspu_click_cnt_7d/cspu_imp_cnt_7d,0) -- 选出变坏的preferred的组合key
and preferred_imp_cnt_7d>0 and cspu_imp_cnt_7d>0 -- 理论上不会出现负数，但是出现了，这里就让本次回退圈选失效。
;
--sql_divide_splitter--
-- 这是一个版本升级记录累计表，会记录每一个组合key的升级记录，下游用的时候，更具task运行日，进行过滤筛选使用
INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_pb_search_replace_monitoring_nd partition(grass_region = ${grass_region}, local_date=${local_date})
SELECT
     if(a.exp_tag is not null ,a.exp_tag,b.exp_tag) as exp_tag
    ,if(a.cspu_id is not null ,a.cspu_id,b.cspu_id) as cspu_id
    ,if(a.item_id is not null ,a.item_id,b.item_id) as item_id
    ,if(a.version_date is not null ,a.version_date,b.version_date) as version_date
FROM last_monitoring_${grass_region_without_quote} a
full outer join update_version_list_${grass_region_without_quote} b
    on a.item_id=b.item_id and a.cspu_id=b.cspu_id and a.exp_tag=b.exp_tag
    and  a.version_date=b.join_key_date  -- 用昨日日期关联，如果历史分区已经有了，那就暂时不升级，等一天
;
